_LCP = [[720, 72, 144, 116, 187, 72, 144, 114, 97, 72, 114, 72, 116, 72, 97, 72, 144, 97, 72], [72, 720, 72, 72, 72, 91, 72, 72, 72, 112, 72, 152, 72, 152, 72, 112, 72, 72, 152], [144, 72, 720, 116, 144, 72, 153, 114, 97, 72, 114, 72, 116, 72, 97, 72, 152, 97, 72], [116, 72, 116, 720, 116, 72, 116, 114, 97, 72, 114, 72, 144, 72, 97, 72, 116, 97, 72], [187, 72, 144, 116, 720, 72, 144, 114, 97, 72, 114, 72, 116, 72, 97, 72, 144, 97, 72], [72, 91, 72, 72, 72, 720, 72, 72, 72, 91, 72, 91, 72, 91, 72, 91, 72, 72, 91], [144, 72, 153, 116, 144, 72, 720, 114, 97, 72, 114, 72, 116, 72, 97, 72, 152, 97, 72], [114, 72, 114, 114, 114, 72, 114, 720, 97, 72, 152, 72, 114, 72, 97, 72, 114, 97, 72], [97, 72, 97, 97, 97, 72, 97, 97, 720, 72, 97, 72, 97, 72, 144, 72, 97, 217, 72], [72, 112, 72, 72, 72, 91, 72, 72, 72, 720, 72, 112, 72, 112, 72, 144, 72, 72, 112], [114, 72, 114, 114, 114, 72, 114, 152, 97, 72, 720, 72, 114, 72, 97, 72, 114, 97, 72], [72, 152, 72, 72, 72, 91, 72, 72, 72, 112, 72, 720, 72, 175, 72, 112, 72, 72, 152], [116, 72, 116, 144, 116, 72, 116, 114, 97, 72, 114, 72, 720, 72, 97, 72, 116, 97, 72], [72, 152, 72, 72, 72, 91, 72, 72, 72, 112, 72, 175, 72, 720, 72, 112, 72, 72, 152], [97, 72, 97, 97, 97, 72, 97, 97, 144, 72, 97, 72, 97, 72, 720, 72, 97, 144, 72], [72, 112, 72, 72, 72, 91, 72, 72, 72, 144, 72, 112, 72, 112, 72, 720, 72, 72, 112], [144, 72, 152, 116, 144, 72, 152, 114, 97, 72, 114, 72, 116, 72, 97, 72, 720, 97, 72], [97, 72, 97, 97, 97, 72, 97, 97, 217, 72, 97, 72, 97, 72, 144, 72, 97, 720, 72], [72, 152, 72, 72, 72, 91, 72, 72, 72, 112, 72, 152, 72, 152, 72, 112, 72, 72, 720]]
_START = 13
_STATE = {}
_COMMIT = {}


def agent(obs, config=None):
    step = int(obs.get("step", 0) or 0)
    if step == 0 or "cur" not in _STATE:
        _STATE["cur"] = _START
        _COMMIT.clear()
    shops = tuple((obs.get("town") or {}).get("unlocked_shops") or [])
    if step in _BRANCH_STEPS:
        k = _BRANCH_STEPS.index(step); cur = _STATE["cur"]
        cand = [j for j in range(len(_CINTAS))
                if (j == cur or _LCP[cur][j] >= step)
                and len(_CINTAS[j][2]) > k and _CINTAS[j][2][k] == shops]
        if cand:
            _STATE["cur"] = max(cand, key=lambda j: _CINTAS[j][1])
    acts = _CINTAS[_STATE["cur"]][3]
    action = json.loads(json.dumps(acts[min(step, len(acts) - 1)]))
    return guard_commitments(obs, guard_cash(obs, action, reserve=6), _COMMIT)
